// package.json "main" -- SUPERSEDED by "exports". Under real Node no
// importer can reach this file through the package name. It exports the
// advisory's literal name on purpose: an absolute-PATH request for the
// install directory resolves HERE (a path request never consults
// `exports`), which is exactly the probe P1-A3 had to close.
exports.vulnerable = function legacyDanger(input) {
  return "expmain-legacy:" + input;
};
